import crypto from "node:crypto";
import JSZip from "jszip";

export const PREFLIGHT_DISCLAIMER =
  "This Preflight Report and Evidence Package is an independent preparedness assessment " +
  "generated by CarbonFlow Preflight. It is NOT a formal certification, verification, or " +
  "credit issuance under any carbon standard (e.g. Verra VCS, Gold Standard, UNFCCC, ACR). " +
  "All findings, reconciliation checks, and readiness determinations are algorithmic and " +
  "advisory. The project proponent remains solely responsible for the accuracy of all submitted " +
  "monitoring data and claims.";

export type VerificationReadiness = "BLOCKED" | "ACTION_REQUIRED" | "READY_FOR_VERIFICATION";

export type ReportFinding = {
  id: string;
  rule_code: string;
  severity: "critical" | "material" | "minor";
  status: "open" | "acknowledged" | "resolved" | "dismissed";
  title: string;
  detail: string;
  remediation?: string;
  quotes?: string[];
  reviewed_by?: string;
  review_comment?: string;
};

export type ReportDocument = {
  id: string;
  name: string;
  sha256: string;
  media_type: string;
  page_count?: number;
};

export type EvidenceManifest = {
  manifest_version: string;
  generator: string;
  generated_at: string;
  disclaimer: string;
  run_id: string;
  project_id: string;
  monitoring_period_id: string;
  org_id: string;
  project_name?: string;
  methodology?: string;
  verification_readiness: VerificationReadiness;
  readiness_reasons: string[];
  stats: {
    total_documents: number;
    total_findings: number;
    open_findings: number;
    critical_findings: number;
    material_findings: number;
    minor_findings: number;
    resolved_findings: number;
    dismissed_findings: number;
  };
  documents: ReportDocument[];
  findings: ReportFinding[];
  content_hash?: string;
};

/** Compute canonical SHA-256 hexadecimal hash with deterministic key ordering. */
export function canonicalJsonHash(data: unknown): string {
  const canonical = canonicalJsonStringify(data);
  return crypto.createHash("sha256").update(canonical, "utf8").digest("hex");
}

function canonicalJsonStringify(obj: unknown): string {
  if (obj === null || typeof obj !== "object") {
    return JSON.stringify(obj);
  }
  if (Array.isArray(obj)) {
    return `[${obj.map((item) => canonicalJsonStringify(item)).join(",")}]`;
  }
  const keys = Object.keys(obj as Record<string, unknown>).sort();
  const entries = keys.map(
    (k) => `${JSON.stringify(k)}:${canonicalJsonStringify((obj as Record<string, unknown>)[k])}`
  );
  return `{${entries.join(",")}}`;
}

/** Build an EvidenceManifest with readiness status and canonical hash. */
export function buildEvidenceManifest(input: {
  run_id: string;
  project_id: string;
  monitoring_period_id: string;
  org_id: string;
  project_name?: string;
  methodology?: string;
  documents: ReportDocument[];
  findings: ReportFinding[];
}): EvidenceManifest {
  const { run_id, project_id, monitoring_period_id, org_id, project_name, methodology, documents, findings } = input;

  const reasons: string[] = [];
  const openFindings = findings.filter((f) => f.status === "open" || f.status === "acknowledged");
  const critOpen = openFindings.filter((f) => f.severity === "critical");
  const matOpen = openFindings.filter((f) => f.severity === "material");

  let readiness: VerificationReadiness = "READY_FOR_VERIFICATION";
  if (critOpen.length > 0) {
    readiness = "BLOCKED";
    reasons.push(`${critOpen.length} critical finding(s) remain open or unverified.`);
  } else if (matOpen.length > 0) {
    readiness = "ACTION_REQUIRED";
    reasons.push(`${matOpen.length} material finding(s) require remediation before verification.`);
  } else {
    reasons.push("All critical and material findings have been resolved or addressed.");
  }

  const manifestWithoutHash: Omit<EvidenceManifest, "content_hash"> = {
    manifest_version: "1.0.0",
    generator: "CarbonFlow Preflight v0.2.0",
    generated_at: new Date().toISOString(),
    disclaimer: PREFLIGHT_DISCLAIMER,
    run_id,
    project_id,
    monitoring_period_id,
    org_id,
    project_name,
    methodology,
    verification_readiness: readiness,
    readiness_reasons: reasons,
    stats: {
      total_documents: documents.length,
      total_findings: findings.length,
      open_findings: openFindings.length,
      critical_findings: findings.filter((f) => f.severity === "critical").length,
      material_findings: findings.filter((f) => f.severity === "material").length,
      minor_findings: findings.filter((f) => f.severity === "minor").length,
      resolved_findings: findings.filter((f) => f.status === "resolved").length,
      dismissed_findings: findings.filter((f) => f.status === "dismissed").length,
    },
    documents,
    findings,
  };

  const hash = canonicalJsonHash(manifestWithoutHash);
  return {
    ...manifestWithoutHash,
    content_hash: hash,
  };
}

/** Generate a GitHub-flavored Markdown preflight report. */
export function generateMarkdownReport(manifest: EvidenceManifest): string {
  const lines: string[] = [];

  lines.push("# CarbonFlow Preflight — Preflight Verification Report");
  lines.push("");
  lines.push(`> **Verification Readiness: ${manifest.verification_readiness}**  `);
  manifest.readiness_reasons.forEach((r) => lines.push(`> ${r}  `));
  lines.push("");
  lines.push("---");
  lines.push("");
  lines.push("## 1. Executive Summary");
  lines.push("");
  lines.push(`- **Run ID**: \`${manifest.run_id}\``);
  lines.push(`- **Project**: ${manifest.project_name || manifest.project_id}`);
  lines.push(`- **Monitoring Period**: \`${manifest.monitoring_period_id}\``);
  if (manifest.methodology) {
    lines.push(`- **Methodology**: ${manifest.methodology}`);
  }
  lines.push(`- **Generated At**: ${manifest.generated_at}`);
  lines.push(`- **Manifest Content Hash (SHA-256)**: \`${manifest.content_hash}\``);
  lines.push("");
  lines.push("### Findings Summary");
  lines.push("");
  lines.push("| Category | Total | Open | Resolved / Dismissed |");
  lines.push("| :--- | :--- | :--- | :--- |");
  lines.push(
    `| **Critical** | ${manifest.stats.critical_findings} | ${manifest.findings.filter((f) => f.severity === "critical" && f.status === "open").length} | ${manifest.findings.filter((f) => f.severity === "critical" && (f.status === "resolved" || f.status === "dismissed")).length} |`
  );
  lines.push(
    `| **Material** | ${manifest.stats.material_findings} | ${manifest.findings.filter((f) => f.severity === "material" && f.status === "open").length} | ${manifest.findings.filter((f) => f.severity === "material" && (f.status === "resolved" || f.status === "dismissed")).length} |`
  );
  lines.push(
    `| **Minor** | ${manifest.stats.minor_findings} | ${manifest.findings.filter((f) => f.severity === "minor" && f.status === "open").length} | ${manifest.findings.filter((f) => f.severity === "minor" && (f.status === "resolved" || f.status === "dismissed")).length} |`
  );
  lines.push("");
  lines.push("---");
  lines.push("");
  lines.push("## 2. Evidence Documents and Cryptographic Hashes");
  lines.push("");
  lines.push("| Document Name | Format | SHA-256 Digest |");
  lines.push("| :--- | :--- | :--- |");
  manifest.documents.forEach((d) => {
    lines.push(`| ${d.name} | ${d.media_type} | \`${d.sha256}\` |`);
  });
  lines.push("");
  lines.push("---");
  lines.push("");
  lines.push("## 3. Findings Register & Human Review Log");
  lines.push("");
  if (manifest.findings.length === 0) {
    lines.push("*No findings were identified for this monitoring period.*");
  } else {
    manifest.findings.forEach((f, idx) => {
      lines.push(`### ${idx + 1}. [${f.rule_code}] ${f.title}`);
      lines.push(`- **Severity**: \`${f.severity.toUpperCase()}\``);
      lines.push(`- **Status**: \`${f.status.toUpperCase()}\``);
      lines.push(`- **Detail**: ${f.detail}`);
      if (f.remediation) {
        lines.push(`- **Remediation**: ${f.remediation}`);
      }
      if (f.quotes && f.quotes.length > 0) {
        lines.push("- **Cited Document Evidence**:");
        f.quotes.forEach((q) => lines.push(`  > "${q}"`));
      }
      if (f.review_comment) {
        lines.push(`- **Review Justification**: *${f.review_comment}*`);
      }
      lines.push("");
    });
  }
  lines.push("");
  lines.push("---");
  lines.push("");
  lines.push("## 4. Legal Disclaimer");
  lines.push("");
  lines.push(`> ${manifest.disclaimer}`);
  lines.push("");

  return lines.join("\n");
}

/** Generate a CSV Reconciliation Workbook. */
export function generateCsvWorkbook(manifest: EvidenceManifest): string {
  const escapeCsv = (val: string | number | undefined | null) => {
    if (val === undefined || val === null) return '""';
    const s = String(val).replace(/"/g, '""');
    return `"${s}"`;
  };

  const rows: string[][] = [];
  rows.push([
    "Finding ID",
    "Rule Code",
    "Severity",
    "Status",
    "Title",
    "Detail",
    "Remediation",
    "Evidence Quotes",
    "Review Justification",
  ]);

  manifest.findings.forEach((f) => {
    rows.push([
      f.id,
      f.rule_code,
      f.severity,
      f.status,
      f.title,
      f.detail,
      f.remediation || "",
      (f.quotes || []).join(" | "),
      f.review_comment || "",
    ]);
  });

  return rows.map((r) => r.map(escapeCsv).join(",")).join("\r\n") + "\r\n";
}

/** Create in-memory ZIP package containing manifest.json, manifest.sha256, preflight_report.md, and findings_workbook.csv. */
export async function createEvidencePackageZip(manifest: EvidenceManifest): Promise<Buffer> {
  const zip = new JSZip();

  const canonicalManifest = canonicalJsonStringify(manifest);
  const manifestSha256 = manifest.content_hash || canonicalJsonHash(manifest);

  zip.file("manifest.json", canonicalManifest);
  zip.file("manifest.sha256", `${manifestSha256}  manifest.json\n`);
  zip.file("preflight_report.md", generateMarkdownReport(manifest));
  zip.file("findings_workbook.csv", generateCsvWorkbook(manifest));

  const content = await zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
  return content;
}
